H.raceManagerId="650f9bb2-f983-4c39-9b98-456d89b19dd2"
H.clockSource,H.clockDomain="WAITING_AUTHORITY_CLOCK",nil
function H.readRaceClock()
  local ok,value,source=pcall(function()
    if H.raceHolder==nil or H.raceHolder.script==nil then
      local go=H.U.GameObject.Find("RaceManager")
      if go~=nil then H.raceHolder=go:GetDouyinScript(H.raceManagerId)end
    end
    local script=H.raceHolder and H.raceHolder.script or nil
    if script==nil or script.GetRaceManagerClockReady==nil or not script.GetRaceManagerClockReady()then return nil,"NOT_READY"end
    local milliseconds=tonumber(script.GetRaceManagerServerUnixMilliseconds())
    local label=script.GetRaceManagerClockSource and tostring(script.GetRaceManagerClockSource())or"ROOM_CLOCK"
    if not milliseconds or milliseconds<1577836800000 or milliseconds>4102444800000 then return nil,"INVALID"end
    return milliseconds/1000,label
  end)
