end
function H.serverNow()
  local rt=H.rt()
  if rt>=H.clockAt then
    H.clockAt=rt+0.5
    local ok,sec=pcall(function()return CS.DouyinUtility.GetServerUnixTime()end)
    sec=ok and tonumber(sec)or nil
    if sec and(sec<1577836800 or sec>4102444800)then sec=nil end
    local raceSeconds,raceSource=H.readRaceClock()
    -- The owner locks the room's clock domain in the replicated snapshot.
    -- A room that started with the existing authoritative race clock continues
    -- in that domain even if raw Unix samples become available later. This
    -- prevents a Jan-epoch race fallback from jumping a five-minute deadline.
    if H.clockDomain==nil then
      if sec then H.clockDomain="SERVER_UNIX"elseif raceSeconds then H.clockDomain="RACE_MANAGER"end
    end
    local value,source=nil,"WAITING_AUTHORITY_CLOCK"
    if H.clockDomain=="RACE_MANAGER"then
      if raceSeconds then value,source=raceSeconds,"RACE_MANAGER:"..tostring(raceSource)end
    elseif H.clockDomain=="SERVER_UNIX"then
      if sec then value,source=sec,"SERVER_UNIX"
      elseif raceSeconds and H.lastServerNow and math.abs(raceSeconds-H.lastServerNow)<4 then
        value,source=raceSeconds,"RACE_MANAGER_ALIGNED:"..tostring(raceSource)
      end
    end
    if value and value~=H.clockSample then H.clockSample,H.clockSampleAt=value,rt end
    H.clockSource=source
  end
  if not H.clockSample or rt-H.clockSampleAt>3 or rt<H.clockSampleAt then return nil end
  local value=H.clockSample+(rt-H.clockSampleAt)
  H.lastServerNow=math.max(H.lastServerNow or value,value);return H.lastServerNow
end
function H.playersRefresh()
  local ok,ps=pcall(function()return CS.DouyinPlayerService.GetPlayers()end)
  if not ok or not ps then return end
  local nextPlayers,presentIdentities,idByIdentity={},{},{}
  for i=0,ps.Length-1 do
    local valid,actor,id=pcall(function()local p=ps[i];return p:GetActor(),tostring(p.playerOpenID or "")end)
    if valid and id~="" then presentIdentities[H.hash(id)]=true end
    if valid and actor and id~="" and tonumber(actor.actorID)>0 then nextPlayers[tonumber(actor.actorID)]={actor=actor,openId=id,identity=H.hash(id)};idByIdentity[H.hash(id)]=tonumber(actor.actorID) end
  end
  H.players,H.presentIdentities,H.idByIdentity=nextPlayers,presentIdentities,idByIdentity
end
function H.npc(id)
  local go=H.npcCache[id]
  if go==nil then go=H.U.GameObject.Find(H.models[id].rootName);H.npcCache[id]=go end
  return go
end
function H.publish()
