  for _,id in ipairs(ids)do local r=H.rows[id];lines[#lines+1]=table.concat({id,r.identity,r.preset,r.previous or 0,string.format("%.3f",r.applyAt),string.format("%.3f",r.expiresAt),r.requestRevision},"^")end
