    if #v~=7 or not id or id<=0 or id~=math.floor(id) or rows[id] or not preset or not H.models[preset] or not previous or previous<0 or previous>5 or not applyAt or not expiresAt or math.abs(expiresAt-applyAt-H.duration)>.01 or not rr or not string.match(v[2] or "","^[0-9a-f]+$") or #v[2]~=8 then return false end
