  H.rows,H.revision,H.payload=rows,rev,payload;return true
end
function H.material(hex,glow)
  local key=hex..(glow and "G" or "N");if H.materials[key]then return H.materials[key]end
  local shader=H.U.Shader.Find("Universal Render Pipeline/Lit") or H.U.Shader.Find("Standard") or H.U.Shader.Find("Unlit/Color")
  if not shader then error("HALLOWEEN_SHADER_UNAVAILABLE")end
  local m=H.U.Material(shader);m.name="HalloweenNPC_"..key
  local c=H.U.Color(tonumber(string.sub(hex,1,2),16)/255,tonumber(string.sub(hex,3,4),16)/255,tonumber(string.sub(hex,5,6),16)/255,1)
