-- Reapply the authored palette only to the five newly imported NPC bodies.
-- Some native op2 asset materials arrive with an overriding red property block.
-- Preserve both their material arrays and property blocks before replacing the
-- exact named part's material with the same owned cache used by player forms.
H.staticStyle={nextAt=0,attempts={},done={},originals={},errors={}}
function H.styleStaticNpcs()
  local state=H.staticStyle
  if H.rt()<state.nextAt then return end;state.nextAt=H.rt()+2
  for id,model in ipairs(H.models)do
    if not state.done[id]and(state.attempts[id]or 0)<30 then
      state.attempts[id]=(state.attempts[id]or 0)+1
      local ok,reason=pcall(function()
        local root=H.npc(id);if not root then return "NPC_ROOT_NOT_READY"end
        local expected,found={},{}
        for _,spec in ipairs(model.parts)do expected[spec.name]=spec end
        local renderers=root:GetComponentsInChildren(typeof(H.U.Renderer),true)
        for i=0,renderers.Length-1 do
          local renderer=renderers[i];local spec=expected[tostring(renderer.gameObject.name)]
          if spec then
            if state.originals[renderer]==nil then
              local original={materials=renderer.sharedMaterials,block=H.U.MaterialPropertyBlock(),indexed={}}
              renderer:GetPropertyBlock(original.block)
              for slot=0,original.materials.Length-1 do local block=H.U.MaterialPropertyBlock();renderer:GetPropertyBlock(block,slot);original.indexed[slot]=block end
              state.originals[renderer]=original
            end
            renderer.sharedMaterial=H.material(spec.color,false)
            -- Clear inherited native asset tint without changing the saved
            -- snapshot. The original PropertyBlocks are restored on destroy.
            renderer:SetPropertyBlock(nil)
            for slot=0,renderer.sharedMaterials.Length-1 do renderer:SetPropertyBlock(nil,slot)end
            found[spec.name]=true
          end
        end
        local missing=0;for name,_ in pairs(expected)do if not found[name]then missing=missing+1 end end
        if missing==0 then state.done[id]=true;return nil end
        return "NPC_PARTS_NOT_READY:"..missing
      end)
      state.errors[id]=ok and reason or tostring(reason)
      if state.attempts[id]>=30 and not state.done[id]then state.errors[id]="NPC_STYLE_RETRY_LIMIT:"..tostring(state.errors[id])end
    end
  end
end
function H.restoreStaticNpcMaterials()
  for renderer,original in pairs(H.staticStyle.originals)do
    pcall(function()
      renderer.sharedMaterials=original.materials;renderer:SetPropertyBlock(original.block)
      for slot,block in pairs(original.indexed)do renderer:SetPropertyBlock(block,slot)end
    end)
  end
  H.staticStyle.originals={}
end
function H.staticStyleStatus()
  local done,errors=0,{}
  if H.staticStyle.lastError then errors[#errors+1]=tostring(H.staticStyle.lastError)end
  for id=1,5 do if H.staticStyle.done[id]then done=done+1 elseif H.staticStyle.errors[id]then errors[#errors+1]=id..":"..tostring(H.staticStyle.errors[id])end end
  return tostring(done).."/5",table.concat(errors,";")
end
function H.primitive(name,shape,hex,parent)
  local typ=H.U.PrimitiveType.Sphere
  if shape=="cube" then typ=H.U.PrimitiveType.Cube elseif shape=="cylinder" then typ=H.U.PrimitiveType.Cylinder end
  local go=H.U.GameObject.CreatePrimitive(typ);go.name=name
  if parent then go.transform:SetParent(parent.transform,false)end
  local c=go:GetComponent(typeof(H.U.Collider));if c then c.enabled=false;H.U.Object.Destroy(c)end
  go:GetComponent(typeof(H.U.Renderer)).sharedMaterial=H.material(hex,false)
  return go
end
function H.vec(v) return H.U.Vector3(v[1],v[2],v[3])end
function H.build(preset,name)
