function H.effect(id,row,actor,now)
  local effect=H.effects[id]
  if effect and effect.revision~=row.requestRevision then H.U.Object.Destroy(effect.root);H.effects[id]=nil;effect=nil end
  if now>=row.applyAt then if effect then H.U.Object.Destroy(effect.root);H.effects[id]=nil end;return end
  if not effect then
    local root=H.U.GameObject("Halloween_TransformSpell_"..id);effect={root=root,parts={},revision=row.requestRevision}
    for i=1,16 do local go=H.primitive("CandySpark_"..i,"sphere",i%2==0 and "F6A244" or "8CDBC1",root);go:GetComponent(typeof(H.U.Renderer)).sharedMaterial=H.material(i%2==0 and "F6A244" or "8CDBC1",true);effect.parts[i]=go end
    H.effects[id]=effect
  end
