  local origin=actor.position
  for i,go in ipairs(effect.parts)do local a=progress*math.pi*5+i*math.pi/8;local radius=.36+.28*math.sin(progress*math.pi);local y=.12+1.65*((progress+i/16)%1)
    go.transform.position=origin+H.U.Vector3(math.cos(a)*radius,y,math.sin(a)*radius);local size=.035+.035*math.sin(progress*math.pi);go.transform.localScale=H.U.Vector3.one*size
  end
end
function H.render(now)
  local localText=""
  for id,entry in pairs(H.entries)do
    local row,p=H.rows[id],H.players[id]
    if not row or not p or p.identity~=row.identity or entry.actor~=p.actor or now>=row.expiresAt then H.restore(entry);H.entries[id]=nil end
  end
  for id,effect in pairs(H.effects)do local r=H.rows[id];if not r or not H.players[id]or now>=r.applyAt then H.U.Object.Destroy(effect.root);H.effects[id]=nil end end
  for id,row in pairs(H.rows)do
    local p=H.players[id]
    if p and p.identity==row.identity and now<row.expiresAt then
      H.effect(id,row,p.actor,now)
      local preset=now>=row.applyAt and row.preset or row.previous
      local entry=H.entries[id]
      if preset>0 and(not entry or entry.preset~=preset)then
        local candidate=H.build(preset,"Halloween_ActorBody_"..id)
        if candidate then candidate.actor=p.actor;if H.poseActor(candidate,p.actor)then
          -- Preserve the first player baseline across refreshed or changed forms.
          if entry then candidate.originals,candidate.accessories,candidate.originalAnimators=entry.originals,entry.accessories,entry.originalAnimators or {};H.U.Object.Destroy(entry.root)end
          H.entries[id]=candidate;entry=candidate
        else H.restore(candidate)end end
      end
      if entry then local valid=H.poseActor(entry,p.actor);entry.root:SetActive(valid);if valid then H.hideRenderers(entry)else H.restore(entry);H.entries[id]=nil end end
      if p.actor.isLocal then
        if now<row.applyAt then localText=H.names[row.preset].."："..H.dialogues[row.preset].."\n糖光变身中…"
        else local rem=math.max(0,math.ceil(row.expiresAt-now));localText=H.names[row.preset].." · "..string.format("%d:%02d",math.floor(rem/60),rem%60).." 后恢复本人形象"end
      end
    end
  end
  H.hud(localText)
end
function HalloweenAuthorityRequest(actorId,openId,preset,requestId)
  if not H.owner()then return false,"NOT_OWNER"end
  H.playersRefresh();H.hydrate()
  actorId,preset=tonumber(actorId),tonumber(preset);local p=H.players[actorId];local now=H.serverNow();local npc=H.npc(preset)
  if not p or p.openId~=tostring(openId or "")or not H.models[preset]or not now or not npc then return false,"INVALID_IDENTITY_RESOURCE_OR_CLOCK"end
  if p.actor:IsSitting()then return false,"ALREADY_SEATED"end
  if(H.rt()-(H.lastRequestAt[actorId]or-100))<.75 then return false,"COOLDOWN"end
  if(p.actor.position-npc.transform.position).magnitude>H.requestDistance then return false,"OUT_OF_RANGE"end
  H.lastRequestAt[actorId]=H.rt()
  local previous=H.rows[actorId];local prior=previous and previous.identity==p.identity and previous.expiresAt>now and(now>=previous.applyAt and previous.preset or previous.previous)or 0
  local applyAt=now+H.effectSeconds
  H.rows[actorId]={identity=p.identity,preset=preset,previous=prior,applyAt=applyAt,expiresAt=applyAt+H.duration,requestRevision=H.revision+1}
  H.publish();return true,"SPELL_STARTED"
end
function HalloweenRequestTransform(preset)
  local actor=CS.DouyinActorService.GetLocalActor();if not actor then return false,"NO_LOCAL_ACTOR"end
  H.playersRefresh();local p=H.players[tonumber(actor.actorID)];if not p then return false,"NO_IDENTITY"end
  if H.owner()then return HalloweenAuthorityRequest(tonumber(actor.actorID),p.openId,preset,H.rt())end
  local ok=pcall(function()self:SendMessageToOwner("HalloweenAuthorityRequest",tonumber(actor.actorID),p.openId,tonumber(preset),H.rt())end)
  return ok,ok and"REQUEST_SENT"or"REQUEST_FAILED"
end
function HalloweenGetStatus()
  local styled,styleError=H.staticStyleStatus()
  local count,effects=0,0;for _ in pairs(H.entries)do count=count+1 end;for _ in pairs(H.effects)do effects=effects+1 end
  return "HAVA2|revision="..H.revision.."|bodies="..count.."|effects="..effects.."|clock="..tostring(H.serverNow()).."|clocksource="..tostring(H.clockSource).."|domain="..tostring(H.clockDomain).."|error="..tostring(H.lastError or"none").."|staticNPCStyle="..styled.."|staticNPCStyleError="..(styleError~=""and styleError or"none")
end
function HalloweenGetActorStatus(id)
  local r,e=H.rows[tonumber(id)],H.entries[tonumber(id)]
  return r and table.concat({r.preset,r.applyAt,r.expiresAt,r.identity,e and e.preset or 0,math.max(0,math.ceil(r.expiresAt-(H.serverNow() or r.applyAt)))},"|")or"ORIGINAL"
end
function Start() H.playersRefresh();H.hydrate();H.serverNow()end
function OnNetSpawned()H.playersRefresh();H.hydrate()end
function OnVariablesSynced()H.hydrate()end
function OnOwnershipTransferred()H.hydrate();H.playersRefresh();H.tickAt=0 end
function OnPlayerJoined()H.playersRefresh();H.hydrate()end
function OnPlayerRejoined()H.playersRefresh();H.hydrate()end
function OnPlayerLeft()H.tickAt=0 end
function OnActorSpawned()H.playersRefresh()end
function OnActorRespawn()H.playersRefresh()end
function Update()
  if H.destroyed then return end
  local styled,styleError=pcall(H.styleStaticNpcs)
  if not styled then H.staticStyle.lastError=tostring(styleError)end
  local ok,err=pcall(function()
    if H.rt()<H.tickAt then return end;H.tickAt=H.rt()+.2;H.playersRefresh();H.hydrate()
    local now=H.serverNow();if not now then H.hud("节日魔法等待房间时间同步…");return end
    if H.owner()then
      local changed,moves=false,{}
      for id,row in pairs(H.rows)do
        local replacement=H.idByIdentity and H.idByIdentity[row.identity]
        if now>=row.expiresAt or not H.presentIdentities[row.identity]then H.rows[id]=nil;changed=true
        elseif replacement and replacement~=id then moves[#moves+1]={from=id,to=replacement,row=row}end
      end
      for _,move in ipairs(moves)do H.rows[move.from]=nil;H.rows[move.to]=move.row;changed=true end
      if changed then H.publish()end
    end
  end)
  if not ok then H.lastError=tostring(err)end
end
function LateUpdate()
  if H.destroyed then return end
  local now=H.serverNow()
  if now then
    local ok,err=pcall(function()H.render(now)end)
    if not ok then
      H.lastError=tostring(err)
      for id,entry in pairs(H.entries)do H.restore(entry);H.entries[id]=nil end
      H.hud("魔法外观暂未就绪，已保留本人形象。")
    end
  else
    -- Fail visible after loss of the trusted server sample. Never leave a
    -- hidden player if appearance clocks or rendering resources are unavailable.
    for id,entry in pairs(H.entries)do H.restore(entry);H.entries[id]=nil end
    for id,effect in pairs(H.effects)do H.U.Object.Destroy(effect.root);H.effects[id]=nil end
  end
end
function OnDisable()
  for id,entry in pairs(H.entries)do H.restore(entry);H.entries[id]=nil end
  for id,effect in pairs(H.effects)do H.U.Object.Destroy(effect.root);H.effects[id]=nil end
  if H.hudRoot then H.hudRoot:SetActive(false)end
end
function OnDestroy()
  H.destroyed=true;OnDisable();H.restoreStaticNpcMaterials();if H.root then H.U.Object.Destroy(H.root)end;if H.hudRoot then H.U.Object.Destroy(H.hudRoot)end
  for _,m in pairs(H.materials)do H.U.Object.Destroy(m)end;if H.fontOwned and H.font then H.U.Object.Destroy(H.font)end
end


