-- Preserve continuous HD garments with GPU four-weight skinning.
-- Static imported pieces supply UVs/materials; identical seam coordinates get
-- identical weights. Skin assets are built once and shared by player instances.
H.hdSkinAssets,H.hdSkinErrors={},{}
function H.skinSmooth(a,b,x)local t=math.max(0,math.min(1,(x-a)/(b-a)));return t*t*(3-2*t)end
function H.skinWeights(p,preset)
 local x,z=math.abs(p.x),p.y;local side=p.x>0 and'Left'or'Right';local smooth=H.skinSmooth
 if z>1.31 then local t=smooth(1.31,1.43,z);return {Head=t,Neck=1-t}end
 if z<.86 and(preset==3 or x>.205)then return {Hips=.92,Spine=.08}end
 if z<.84 then
  if z<.20 then local t=smooth(.10,.20,z);return {[side..'Foot']=1-t,[side..'LowerLeg']=t}end
  local t=smooth(.39,.55,z);return {[side..'LowerLeg']=1-t,[side..'UpperLeg']=t}
 end
 local t=smooth(.91,1.10,z);local w={Hips=(1-t)*.45,Spine=(1-t)*.55,Chest=t}
 local arm=smooth(.18,.25,x)*(1-smooth(1.255,1.34,z))
 if arm>0 then
  local chain
  if z<.94 then local a=smooth(.79,.94,z);chain={[side..'Hand']=1-a,[side..'LowerArm']=a}
  else local a=smooth(.99,1.14,z);chain={[side..'LowerArm']=1-a,[side..'UpperArm']=a}end
  for name,v in pairs(w)do w[name]=v*(1-arm)end
  for name,v in pairs(chain)do w[name]=v*arm end
 end
 return w
end
function H.skinCreateAssets(template,preset)
 local U=H.U;local rig=H.hdSkinRigs[tostring(preset)];if not rig then return nil end
 H.templateHeight(template)
 local assets={meshes={},names={},indices={},sourceStates={},boneStates={}};local frame=template.bones.Root.transform.parent
 for name,node in pairs(template.bones)do assets.boneStates[name]={p=node.restPosition,q=node.restRotation}end
 for name in pairs(template.bones)do assets.names[#assets.names+1]=name end;table.sort(assets.names)
 for i,name in ipairs(assets.names)do assets.indices[name]=i-1 end
 -- Capture all original rest vertices before changing any bone pivot.
 for _,part in ipairs(template.parts)do
  local original=part.filter.sharedMesh;local vertices=original.vertices;local normals=original.normals
  local matrix=template.root.transform.worldToLocalMatrix*part.filter.transform.localToWorldMatrix
  local normalMatrix=matrix.inverse.transpose;local out=CS.System.Array.CreateInstance(typeof(U.Vector3),vertices.Length)
  local outNormals=CS.System.Array.CreateInstance(typeof(U.Vector3),vertices.Length)
  local weights=CS.System.Array.CreateInstance(typeof(U.BoneWeight),vertices.Length)
  local delta=CS.System.Array.CreateInstance(typeof(U.Vector3),vertices.Length)
  local zero=CS.System.Array.CreateInstance(typeof(U.Vector3),vertices.Length)
  local map=template.map
  for i=0,vertices.Length-1 do
   local v=vertices[i];local world=part.filter.transform:TransformPoint(v);local f=frame:InverseTransformPoint(world)
