H.skinDestroyBase=OnDestroy
function OnDestroy()
 for preset,assets in pairs(H.hdSkinAssets)do
  local template=H.nativeTemplates[preset]
  if template then
   for _,part in ipairs(template.skinParts or{})do if part.go then H.U.Object.Destroy(part.go)end end
   for name,state in pairs(assets.boneStates)do local node=template.bones[name];if node then
    node.restPosition,node.restRotation=state.p,state.q
    for _,t in ipairs(node.instances or{node.transform})do pcall(function()t.localPosition=state.p;t.localRotation=state.q end)end
   end end
  end
 end
 for _,template in pairs(H.nativeTemplates)do if template.displayOriginalRotation then pcall(function()template.root.transform.rotation=template.displayOriginalRotation end)end end
 H.skinDestroyBase()
 for _,assets in pairs(H.hdSkinAssets)do
  for _,state in ipairs(assets.sourceStates)do pcall(function()state.renderer.enabled=state.enabled end)end
