 local raw=tostring(H.raceHolder.script.GetRaceManagerFinalResultsSnapshot()or'');local h=raw:match('^([^\n]+)');if not h then return nil end
 local f=H.split(h,'|');if f[1]~='GFP1'or tonumber(f[2])~=cycle or f[4]~='final'then return nil end
 local rows={};for line in raw:gmatch('[^\n]+')do local id,rank,ms,vehicle=line:match('^(%d+)|(%d+)|([%d%-]+)|(.+)$');if tonumber(rank)==1 and tonumber(ms)>=0 then rows[#rows+1]={id=tonumber(id),vehicle=vehicle}end end
 if #rows==0 then return nil end
 table.sort(rows,function(a,b)return a.id<b.id end)
 -- Driver has priority when both front/back riders share rank one.
 local ui=H.U.GameObject.Find('RaceManager'):GetDouyinScript('3cb5f0e7-b1a4-4aa0-8d32-905a47bd2f26')
 if ui and ui.script then for _,row in ipairs(rows)do
  local ok,c,driver=pcall(function()return ui.script.GetRaceVehicleSessionState(row.vehicle)end)
  if ok and tonumber(c)==cycle and tonumber(driver)==row.id then return row.id end
 end end
 return nil
end
function H.showStart(cycle,elapsed)
 local S=H.show;local U=H.U;if not H.showPrepareCast()then return false end
 S.cycle=cycle;S.active=true;S.audioStarted=false;S.state='DANCING';S.done[cycle]=true;S.t=elapsed;H.showBgm(true)
 for i,e in ipairs(S.cast)do e.root:SetActive(true);H.showHide(e.template.root)end
 if S.audioReady then S.audio.time=math.min(9.9,elapsed);S.audio:Play();S.audioStarted=true end
 return true
end
function H.showAddWinner(id)
 local S=H.show;local U=H.U;local actor=CS.DouyinActorService.GetActorById(id);if not actor then return false end
 local w=H.showCloneActor(actor);if not w then return false end;S.winner=w;S.winnerId=id
 H.showHide(actor.gameObject)
 local localActor=CS.DouyinActorService.GetLocalActor()
 if actor.isLocal and localActor==actor then
  S.localChampion=actor;S.couldMove=actor:CanMove();actor:StopMove();actor:Immobilize(true)
  S.mainCamera=CS.DouyinCameraService.GetCamera();if S.mainCamera then
   S.cameraWasEnabled=S.mainCamera.enabled;local go=U.GameObject('Halloween_Winner_AudienceCamera');S.camera=go:AddComponent(typeof(U.Camera));S.camera:CopyFrom(S.mainCamera);S.camera.depth=S.mainCamera.depth+10;S.camera.enabled=true;S.mainCamera.enabled=false
  end
 end
 return true
end
function H.showAudioLoad()
 local S=H.show;local U=H.U;if S.audioReady then return end
 if not S.audio then local go=U.GameObject('Halloween_Ceremony_Audio');go.transform:SetParent(S.root.transform,false);S.audio=go:AddComponent(typeof(U.AudioSource));S.audio.loop=false;S.audio.playOnAwake=false;S.audio.volume=.65;S.audio.spatialBlend=0;S.audio.pitch=1;S.audioBlock=1;S.audioCopied=0;S.audioSamples=CS.System.Array.CreateInstance(typeof(CS.System.Single),160000)end
 local encoded=H.victoryAudio[S.audioBlock];if not encoded then return end
 local raw=CS.System.Convert.FromBase64String(encoded);local count=#raw/2;local samples={string.unpack('<'..string.rep('i2',count),raw)};samples[count+1]=nil;for i=1,count do samples[i]=samples[i]/32768 end
 local scratch=U.AudioClip.Create('CeremonyScratch',count,1,16000,false);scratch:SetData(samples,0);local arr=CS.System.Array.CreateInstance(typeof(CS.System.Single),count);scratch:GetData(arr,0);CS.System.Array.Copy(arr,0,S.audioSamples,S.audioCopied,count);U.Object.Destroy(scratch)
 S.audioCopied=S.audioCopied+count;S.audioBlock=S.audioBlock+1
 if S.audioCopied==160000 then S.audioClip=U.AudioClip.Create('ReferenceDance_0_10seconds',160000,1,16000,false);S.audioClip:SetData(S.audioSamples,0);S.audio.clip=S.audioClip;S.audioSamples=nil;S.audioReady=true end
end
-- The ceremony is local presentation: require this actor's completed return
-- for this exact cycle, rather than a previous round's diagnostic status.
function H.showReturnComplete(manager, cycle)
 if not manager or not manager.GetRaceManagerPlayerReturnStatus or cycle<=0 then return false end
 local ok, raw=pcall(function()return manager.GetRaceManagerPlayerReturnStatus()end)
 if not ok then return false end
 local status=tostring(raw or'')
 if tonumber(status:match('^cycle=(%d+)|'))~=cycle or status:match('|stage=([^|]+)|')~='COMPLETED' then return false end
 local returnedActor=status:match('|actor=([^|]+)|')
 local read, actor=pcall(function()return CS.DouyinActorService.GetLocalActor()end)
 if not read or actor==nil then return false end
 local valid, matches=pcall(function()return actor.isLocal==true and tostring(actor.actorID)==returnedActor end)
 return valid and matches==true
end
function H.showTick()
 local S=H.show;if not S.root then H.showBuildStage();return end
 H.showAudioLoad();H.showPrepareCast();H.readRaceClock()
 local manager=H.raceHolder and H.raceHolder.script;if not manager then return end
 local phase=tostring(manager.GetRaceManagerState());local cycle=tonumber(manager.GetRaceManagerCycleId())or 0
 local elapsed=(10000-(tonumber(manager.GetRaceManagerRemainingMilliseconds())or 10000))/1000
 local returned=H.showReturnComplete(manager,cycle)
 local eligible=phase=='RECYCLING'and elapsed>=0 and elapsed<10
 if eligible and not S.active and not S.done[cycle]and returned then H.showStart(cycle,elapsed)end
 if S.active then
  if not eligible or cycle~=S.cycle then H.showStop();return end
  S.t=elapsed
  if S.audioReady and not S.audioStarted then S.audio.time=math.min(9.9,elapsed);S.audio:Play();S.audioStarted=true end
  if not S.winner then local id=H.showPickWinner(cycle);if id then H.showAddWinner(id)end end
  local U=H.U
  for i,e in ipairs(S.cast)do
   e.root.transform.position=S.center+U.Vector3((i-3)*3.4+math.sin(elapsed*math.pi*3.2)*.16,.42,-1.6)
   H.showDancePose(e,elapsed)
  end
  if S.winner then
   H.showHide(S.winner.actor.gameObject);local transformed=H.entries[S.winnerId];if transformed then transformed.root:SetActive(false)end
   H.showWinnerPose(elapsed)
   if S.camera then local x=math.sin(elapsed*.42)*1.2;S.camera.transform.position=S.center+U.Vector3(x,2.3,10.5);S.camera.transform.rotation=U.Quaternion.LookRotation(S.center+U.Vector3(0,1.65,1)-S.camera.transform.position);S.camera.fieldOfView=54 end
  end
  for i,l in ipairs(S.lights)do l.intensity=2.5+.7*math.sin(elapsed*math.pi*3.2+i*.25)end
 else for _,l in ipairs(S.lights)do l.intensity=1.7+.2*math.sin(H.rt())end end
 for k in pairs(S.done)do if k<cycle-1 then S.done[k]=nil end end
end
H.showLateBase=LateUpdate
function LateUpdate()
 if H.showLateBase then H.showLateBase()end
 if H.destroyed then return end
 local ok,err=pcall(H.showTick);if not ok then H.show.error=tostring(err);H.showStop();H.U.Debug.LogError('HalloweenStage '..tostring(err))end
end
H.showDestroyBase=OnDestroy
function OnDestroy()
 local S=H.show;pcall(H.showStop)
 for _,row in ipairs(S.meshes)do pcall(function()row.filter.sharedMesh=row.original end);H.U.Object.Destroy(row.mesh)end
 if S.host then pcall(function()S.host.transform.position=S.hostPosition;S.host.transform.rotation=S.hostRotation end)end
 if S.audioClip then H.U.Object.Destroy(S.audioClip)end
 if S.root then H.U.Object.Destroy(S.root)end
 for _,m in pairs(S.materials)do H.U.Object.Destroy(m)end
 H.showDestroyBase()
end
function HalloweenGetStageStatus()
 local S=H.show;return S.state,S.active==true,S.cycle or 0,S.t or 0,S.winnerId or 0,S.removed or 0,S.audioReady==true,S.error
end

-- Retarget video arm directions in world space. Imported chibi and human rigs
-- use different local bone axes; a shared local Euler curve twists upper arms.
H.victoryElevations={{-15,-10},{-40,10},{-20,40},{0,65},{-50,85},{-20,35},{-30,-20},{-20,-50},{-50,-30},{-10,-10},{15,10},{30,25},{35,35},{15,20},{-20,-30},{-45,-45},{-60,-60},{-30,-10},{-40,-30},{-10,-10},{-15,-10}}
H.victoryLinks={Hips='Spine',Spine='Chest',Chest='Neck',Neck='Head',LeftUpperArm='LeftLowerArm',LeftLowerArm='LeftHand',RightUpperArm='RightLowerArm',RightLowerArm='RightHand',LeftUpperLeg='LeftLowerLeg',LeftLowerLeg='LeftFoot',RightUpperLeg='RightLowerLeg',RightLowerLeg='RightFoot'}
H.victoryOrder={'Hips','Spine','Chest','Neck','LeftUpperArm','LeftLowerArm','RightUpperArm','RightLowerArm','LeftUpperLeg','LeftLowerLeg','RightUpperLeg','RightLowerLeg'}
function H.victoryTargets(t)
 local U=H.U;local index=math.min(20,math.floor(math.max(0,t)*2)+1);local alpha=math.max(0,math.min(1,t*2-(index-1)));alpha=alpha*alpha*(3-2*alpha)
 local a,b=H.victoryElevations[index],H.victoryElevations[index+1];local k,j=H.victoryMotion.keys[index],H.victoryMotion.keys[index+1]
 local pitch=(k[2]+(j[2]-k[2])*alpha)*math.pi/180;local roll=(k[3]+(j[3]-k[3])*alpha)*math.pi/180
 local d={Hips=U.Vector3(0,1,0),Spine=U.Vector3(math.sin(roll)*.4,1,math.sin(pitch)*.5).normalized,Chest=U.Vector3(math.sin(roll),1,math.sin(pitch)).normalized,Neck=U.Vector3(0,1,0)}
 for i,side in ipairs({'Left','Right'})do local sign=i==1 and 1 or-1;local angle=(a[i]+(b[i]-a[i])*alpha)*math.pi/180
  d[side..'UpperArm']=U.Vector3(sign*math.cos(angle),math.sin(angle),.16).normalized
  local fold=math.max(0,math.min(1,(angle-.8)/.4));fold=fold*fold*(3-2*fold);local elbow=angle-.28+.58*fold
  d[side..'LowerArm']=U.Vector3(sign*math.cos(elbow)*.65,math.sin(elbow)*.65,.44).normalized
  local step=math.sin(t*math.pi*3.2)*sign
  d[side..'UpperLeg']=U.Vector3(sign*.06,-1,.10+step*.09).normalized
  d[side..'LowerLeg']=U.Vector3(0,-1,-.10-step*.09).normalized
 end
 return d
end
function H.showDancePose(e,t)
 local U=H.U
 for _,node in pairs(e.bones)do for _,tr in ipairs(node.instances or{node.transform})do tr.localPosition=node.restPosition;tr.localRotation=node.restRotation end end
 if not e.victoryBind then
  e.victoryBind={}
  for name,child in pairs(H.victoryLinks)do local a,b=e.bones[name],e.bones[child];if a and b then
   local dir=(b.transform.position-a.transform.position).normalized;local rows={}
   for _,tr in ipairs(a.instances or{a.transform})do rows[#rows+1]={t=tr,q=tr.rotation}end
   e.victoryBind[name]={direction=dir,rows=rows}
  end end
 end
 local directions=H.victoryTargets(t)
 for _,name in ipairs(H.victoryOrder)do local bind=e.victoryBind[name];local target=directions[name]
  if bind and target then local delta=U.Quaternion.FromToRotation(bind.direction,target)
   for _,row in ipairs(bind.rows)do row.t.rotation=delta*row.q end
  end
 end
 if e.skinParts then for _,p in ipairs(e.skinParts)do p.renderer:SetBlendShapeWeight(0,0)end end
end
function H.showWinnerPose(t)
 local S=H.show;local w=S.winner;if not w then return end;local U=H.U
 w.root.transform.position=S.center+U.Vector3(math.sin(t*math.pi*3.2)*.11,.79,2.2)
 if w.entry then w.root.transform.rotation=w.entry.template.facing;H.showDancePose(w.entry,t)
 else
  w.root.transform.rotation=U.Quaternion.identity;local directions=H.victoryTargets(t)
  for _,name in ipairs(H.victoryOrder)do local b=w.bones[name];local d=directions[name];if b and d then b.transform.rotation=U.Quaternion.FromToRotation(b.direction,d)*b.rotation end end
 end
end

function HalloweenGetVictoryMotionStatus()return 'WORLD_DIRECTION_V2',301,30,10 end

H.showDisableBase=OnDisable
function OnDisable()pcall(H.showStop);if H.showDisableBase then H.showDisableBase()end end
